1	package nexusbench
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"slices"
8		"strings"
9	)
10	
11	// Op is what a run of the bench is about to do; it decides which checks the
12	// preflight makes.
13	type Op int
14	
15	const (
16		OpUp Op = iota
17		OpProvision
18		OpDown
19		OpStatus
20	)
21	
22	// PreflightResult is what a successful preflight learned about the cluster.
23	type PreflightResult struct {
24		// NamespaceExists is true when the bench namespace is there.
25		NamespaceExists bool
26		// NamespaceOurs is true when it carries our managed-by label.
27		NamespaceOurs bool
28		// NodeIP is the InternalIP of the first node that reports one; empty when
29		// none does, which is not an error (the other hosts still work). It is not
30		// read for OpDown.
31		NodeIP string
32	}
33	
34	const (
35		// managedByLabel and managedByValue are the label 00-namespace.yaml.tmpl
36		// puts on the namespace; down deletes a namespace only when it carries it.
37		managedByLabel = "app.kubernetes.io/managed-by"
38		managedByValue = "devdesk-nexus-bench"
39	
40		// nexusServiceName is the Service 30-service.yaml.tmpl creates.
41		nexusServiceName = "nexus"
42	
43		// requestTimeout bounds every call that reaches the API server.
44		requestTimeout = "--request-timeout=10s"
45	)
46	
47	// permissionScope says where a can-i question applies.
48	type permissionScope int
49	
50	const (
51		scopeCluster   permissionScope = iota // no flag: cluster-scoped resources
52		scopeNamespace                        // -n <namespace>
53		scopeAll                              // -A
54	)
55	
56	// permission is one "kubectl auth can-i" question the preflight asks.
57	type permission struct {
58		verb, resource string
59		scope          permissionScope
60	}
61	
62	// permissionsByOp is the list F2 of the plan: what each operation needs. An
63	// operation absent from the map (status) writes nothing and asks nothing.
64	var permissionsByOp = map[Op][]permission{
65		OpUp: {
66			{"create", "namespaces", scopeCluster},
67			{"create", "persistentvolumeclaims", scopeNamespace},
68			{"create", "services", scopeNamespace},
69			{"create", "deployments", scopeNamespace},
70			{"create", "pods/exec", scopeNamespace},
71			{"list", "services", scopeAll},
72			// Server-side apply is a PATCH, also on a second run (the namespace
73			// included), and Deploy reads the pods and the claims of the namespace
74			// while it waits.
75			{"patch", "namespaces", scopeCluster},
76			{"patch", "deployments", scopeNamespace},
77			{"patch", "services", scopeNamespace},
78			{"patch", "persistentvolumeclaims", scopeNamespace},
79			{"get", "pods", scopeNamespace},
80			{"list", "pods", scopeNamespace},
81			{"get", "persistentvolumeclaims", scopeNamespace},
82			{"list", "persistentvolumeclaims", scopeNamespace},
83		},
84		// Provision waits for the Deployment and reads the pods before it execs.
85		OpProvision: {
86			{"create", "pods/exec", scopeNamespace},
87			{"get", "deployments", scopeNamespace},
88			{"list", "pods", scopeNamespace},
89		},
90		OpDown: {{"delete", "namespaces", scopeCluster}},
91	}
92	
93	// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
94	// returns what it learned. Nothing is written to the cluster, whatever the
95	// outcome: a failure here means no write was ever issued. The checks run in a
96	// fixed order and stop at the first failure, so nothing is asked of a cluster
97	// the context does not reach:
98	//
99	//  1. the parameters (no call at all)
100	//  2. the context is in the kubeconfig
101	//  3. the API server answers /readyz
102	//  4. the can-i questions of the operation
103	//  5. the namespace: absent, ours, or foreign
104	//  6. up only: no other Service holds one of our NodePorts
105	//  7. all but down: the InternalIP of the node
106	//
107	// Every failure is a *BenchError.
108	func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
109		var res PreflightResult
110		if err := p.Validate(); err != nil {
111			return res, err
112		}
113		pf := preflight{r: r, p: p}
114		if err := pf.checkContext(ctx); err != nil {
115			return res, err
116		}
117		if err := pf.checkReachable(ctx); err != nil {
118			return res, err
119		}
120		for _, perm := range permissionsByOp[op] {
121			if err := pf.checkPermission(ctx, perm); err != nil {
122				return res, err
123			}
124		}
125		res, err := pf.checkNamespace(ctx, op)
126		if err != nil {
127			return res, err
128		}
129		if op == OpUp {
130			if err := pf.checkNodePorts(ctx); err != nil {
131				return res, err
132			}
133		}
134		if op != OpDown {
135			if res.NodeIP, err = pf.nodeIP(ctx); err != nil {
136				return res, err
137			}
138		}
139		return res, nil
140	}
