147	// local runs a call that does not reach the API server.
148	func (pf preflight) local(ctx context.Context, args ...string) (stdout, stderr string, err error) {
149		out, errOut, err := pf.r.Run(ctx, nil, args...)
150		return string(out), string(errOut), err
151	}
