153	// remote runs a call that reaches the API server, under a request timeout.
154	func (pf preflight) remote(ctx context.Context, args ...string) (stdout, stderr string, err error) {
155		return pf.local(ctx, slices.Concat(args, []string{requestTimeout})...)
156	}
