182	func (pf preflight) checkContext(ctx context.Context) error {
183		args := []string{"config", "get-contexts", "-o", "name"}
184		out, errOut, err := pf.local(ctx, args...)
185		if err != nil {
186			return pf.failure("list the kubeconfig contexts", args, errOut, err)
187		}
188		for _, line := range strings.Split(out, "\n") {
189			if strings.TrimSpace(line) == pf.p.Context {
190				return nil
191			}
192		}
193		return &BenchError{
194			Kind:  ContextNotFound,
195			Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
196			Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
197		}
198	}
