255	func (pf preflight) checkNamespace(ctx context.Context, op Op) (PreflightResult, error) {
256		var res PreflightResult
257		ns := pf.p.Namespace
258		args := []string{"get", "namespace", ns, "-o", "json"}
259		out, errOut, err := pf.remote(ctx, args...)
260		switch {
261		case err != nil && isNotFound(errOut):
262			// Absent: only provision and status need it.
263			if op == OpProvision || op == OpStatus {
264				return res, &BenchError{
265					Kind:  NamespaceMissing,
266					Cause: fmt.Sprintf("namespace %q does not exist", ns),
267					Check: pf.command(args[:3]...) + ", then run `mise run nexus-bench:up`",
268					Err:   err,
269				}
270			}
271			return res, nil
272		case err != nil:
273			return res, pf.failure(fmt.Sprintf("read the namespace %q", ns), args, errOut, err)
274		}
275	
276		var obj namespaceObject
277		if err := json.Unmarshal([]byte(out), &obj); err != nil {
278			return res, &BenchError{
279				Kind:  Unclassified,
280				Cause: fmt.Sprintf("kubectl answered with something that is not a Namespace for %q", ns),
281				Check: pf.command(args...),
282				Err:   err,
283			}
284		}
285		res.NamespaceExists = true
286		res.NamespaceOurs = obj.Metadata.Labels[managedByLabel] == managedByValue
287		if !res.NamespaceOurs {
288			return res, &BenchError{
289				Kind:  NamespaceForeign,
290				Cause: fmt.Sprintf("namespace %q exists but does not carry the label %s=%s, so the bench did not create it", ns, managedByLabel, managedByValue),
291				Check: pf.command("get", "namespace", ns, "--show-labels") + ", or choose another NEXUS_BENCH_NAMESPACE",
292			}
293		}
294		return res, nil
295	}
