363	// nodeIP returns the first InternalIP any node reports, or "" when none does.
364	func (pf preflight) nodeIP(ctx context.Context) (string, error) {
365		args := []string{"get", "nodes", "-o", "json"}
366		out, errOut, err := pf.remote(ctx, args...)
367		if err != nil {
368			return "", pf.failure("read the nodes", args, errOut, err)
369		}
370		var nodes nodeList
371		if err := json.Unmarshal([]byte(out), &nodes); err != nil {
372			return "", &BenchError{
373				Kind:  Unclassified,
374				Cause: "kubectl answered with something that is not a Node list",
375				Check: pf.command(args...),
376				Err:   err,
377			}
378		}
379		for _, node := range nodes.Items {
380			for _, addr := range node.Status.Addresses {
381				if addr.Type == "InternalIP" {
382					return addr.Address, nil
383				}
384			}
385		}
386		return "", nil
387	}
