101	//  3. the API server answers /readyz
102	//  4. the can-i questions of the operation
103	//  5. the namespace: absent, ours, or foreign
104	//  6. up only: no other Service holds one of our NodePorts
105	//  7. all but down: the InternalIP of the node
106	//
107	// Every failure is a *BenchError.
108	func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
