163	// failure turns a failed kubectl call into a BenchError whose kind comes from
164	// the stderr. Neither the stderr nor the sub-process error reaches the message.
165	func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
166		kind := classifyKubectl(stderr)
167		reason := "kubectl failed"
168		switch kind {
169		case Forbidden:
170			reason = "the API server refused the request (forbidden)"
171		case ClusterUnreachable:
172			reason = "the cluster did not answer"
173		}
174		return &BenchError{
175			Kind:  kind,
176			Cause: "could not " + what + ": " + reason,
177			Check: pf.command(args...),
178			Err:   err,
179		}
180	}
