200	func (pf preflight) checkReachable(ctx context.Context) error {
201		args := []string{"get", "--raw", "/readyz"}
202		_, errOut, err := pf.remote(ctx, args...)
203		if err == nil {
204			return nil
205		}
206		// A refusal (an expired token, a 403) is not an absent cluster: say so.
207		// Anything else, classified or not, means the server did not answer.
208		if classifyKubectl(errOut) == Forbidden {
209			return pf.failure("reach the API server", args, errOut, err)
210		}
211		return &BenchError{
212			Kind:  ClusterUnreachable,
213			Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
214			Check: pf.command(args...),
215			Err:   err,
216		}
