219	// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
220	// non-zero exit, so the answer is read before the error.
221	func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
222		args := []string{"auth", "can-i", perm.verb, perm.resource}
223		where := "cluster-wide"
224		switch perm.scope {
225		case scopeNamespace:
226			args = append(args, "-n", pf.p.Namespace)
227			where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
228		case scopeAll:
229			args = append(args, "-A")
230			where = "in all namespaces"
231		}
232		out, errOut, err := pf.remote(ctx, args...)
233		answer := strings.TrimSpace(out)
234		switch {
235		case strings.HasPrefix(answer, "no"):
236			return &BenchError{
237				Kind:  Forbidden,
238				Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.resource, where),
239				Check: pf.command(args...),
240				Err:   err,
241			}
242		case err == nil && strings.HasPrefix(answer, "yes"):
243			return nil
244		}
245		return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.resource), args, errOut, err)
246	}
