312	// checkNodePorts reads every Service of the cluster: the list of taken
313	// NodePorts is not a constant (F1). Our own Service, in our namespace, may hold
314	// them: that is a second up.
315	func (pf preflight) checkNodePorts(ctx context.Context) error {
316		args := []string{"get", "services", "-A", "-o", "json"}
317		out, errOut, err := pf.remote(ctx, args...)
318		if err != nil {
319			return pf.failure("list the Services of the cluster", args, errOut, err)
320		}
321		var list serviceList
322		if err := json.Unmarshal([]byte(out), &list); err != nil {
323			return &BenchError{
324				Kind:  Unclassified,
325				Cause: "kubectl answered with something that is not a Service list",
326				Check: pf.command(args...),
327				Err:   err,
328			}
329		}
330		var taken []string
331		for _, svc := range list.Items {
332			if svc.Metadata.Namespace == pf.p.Namespace && svc.Metadata.Name == nexusServiceName {
333				continue
334			}
335			for _, port := range svc.Spec.Ports {
336				if port.NodePort == pf.p.HTTPNodePort || port.NodePort == pf.p.DockerNodePort {
337					taken = append(taken, fmt.Sprintf("%d is held by Service %s/%s", port.NodePort, svc.Metadata.Namespace, svc.Metadata.Name))
338				}
339			}
340		}
341		if len(taken) > 0 {
342			return &BenchError{
343				Kind:  NodePortTaken,
344				Cause: "NodePort " + strings.Join(taken, ", "),
345				Check: pf.command(args...) + ", then set NEXUS_BENCH_HTTP_NODEPORT and NEXUS_BENCH_DOCKER_NODEPORT to free ports",
346			}
347		}
348		return nil
349	}
