136	func creatingPod() fakePod {
137		return fakePod{phase: "Pending", scheduled: "True", waiting: "ContainerCreating"}
138	}
139	func startingPod() fakePod { return fakePod{phase: "Running", scheduled: "True", running: true} }
140	func readyPod() fakePod {
141		return fakePod{phase: "Running", scheduled: "True", running: true, ready: true}
142	}
143	func unscheduledPod() fakePod { return fakePod{phase: "Pending"} }
144	func unschedulablePod(msg string) fakePod {
