233	// checkRead verifies the namespace, the selector (pods) and the output of a read.
234	func (d *deployKubectl) checkRead(norm []string, withSelector bool) {
235		var ns, selector, output string
236		for i := 2; i < len(norm); i++ {
237			switch norm[i] {
238			case "-n", "--namespace":
239				i++
240				ns = at(norm, i)
241			case "-l", "--selector":
242				i++
243				selector = at(norm, i)
244			case "-o", "--output":
245				i++
246				output = at(norm, i)
247			default:
248				d.t.Errorf("unscripted argument %q in %q", norm[i], norm)
249			}
250		}
251		if ns != d.p.Namespace {
252			d.t.Errorf("%q reads namespace %q, the run is about %q", norm, ns, d.p.Namespace)
253		}
254		if output != "json" {
255			d.t.Errorf("%q must ask for -o json", norm)
256		}
257		if withSelector && selector != deployPodSelector {
258			d.t.Errorf("%q must select %s, got %q", norm, deployPodSelector, selector)
259		}
260	}
261	
262	func at(s []string, i int) string {
263		if i < len(s) {
264			return s[i]
265		}
266		return ""
267	}
