319	// fakeProber answers Ready by the host of the URL and the time of the fake
320	// clock: a host is ready from its entry of readyAfter on, and never when it has
321	// none. It is safe for concurrent use, because Deploy may probe the hosts in
322	// parallel.
323	type fakeProber struct {
324		clk        *fakeClock
325		readyAfter map[string]time.Duration
326	
327		mu   sync.Mutex
328		urls []string
329	}
330	
331	var _ Prober = (*fakeProber)(nil)
332	
333	func (f *fakeProber) Ready(ctx context.Context, baseURL string) error {
334		f.mu.Lock()
335		f.urls = append(f.urls, baseURL)
336		f.mu.Unlock()
337		if err := ctx.Err(); err != nil {
338			return err
339		}
340		u, err := url.Parse(baseURL)
341		if err != nil {
342			return fmt.Errorf("fake prober: bad URL %q: %w", baseURL, err)
343		}
344		if after, ok := f.readyAfter[u.Hostname()]; ok && f.clk.elapsed() >= after {
345			return nil
346		}
347		// The text carries a secret on purpose: it must not reach a message.
348		return fmt.Errorf("dial tcp %s: connect: connection refused (token=%s)", u.Host, fakeSecret)
349	}
350	
351	func (f *fakeProber) probed() []string {
352		f.mu.Lock()
353		defer f.mu.Unlock()
354		return slices.Clone(f.urls)
355	}
