412	// requireTwoApplies checks the writes of a run that got past the preflight:
413	// the Namespace alone, then the whole stream.
414	func (e *deployEnv) requireTwoApplies() {
415		e.t.Helper()
416		got := e.kube.applies
417		if len(got) != 2 {
418			e.t.Fatalf("%d apply calls, want 2 (the Namespace, then everything): %q", len(got), e.kube.lines)
419		}
420		if !bytes.Equal(got[0].stdin, e.kube.nsDoc) {
421			e.t.Errorf("the first apply did not send RenderNamespace(p):\n%s", got[0].stdin)
422		}
423		if !bytes.Equal(got[1].stdin, e.kube.fullDoc) {
424			e.t.Errorf("the second apply did not send Render(p):\n%s", got[1].stdin)
425		}
