463	// requireNoWrite checks nothing was written and nothing was waited for.
464	func (e *deployEnv) requireNoWrite() {
465		e.t.Helper()
466		if len(e.kube.applies) != 0 {
467			e.t.Errorf("Deploy wrote to the cluster: %q", e.kube.lines)
468		}
469		if e.kube.podReads != 0 || e.kube.pvcReads != 0 {
470			e.t.Errorf("Deploy read the pods (%d) or the claims (%d) although it stopped before the apply", e.kube.podReads, e.kube.pvcReads)
471		}
472		if got := e.pr.probed(); len(got) != 0 {
473			e.t.Errorf("Deploy probed %q although it stopped before the apply", got)
474		}
475	}
