565	func TestRunPreflightAsksTheRequiredChecks(t *testing.T) {
566		for op, checks := range requiredChecks {
567			t.Run(testOpName[op], func(t *testing.T) {
568				p := Defaults()
569				f := newFakeKubectl(t, p)
570				if op != OpUp {
571					f.ours()
572				}
573				if _, err := RunPreflight(context.Background(), f, p, op); err != nil {
574					t.Fatalf("RunPreflight: %v", err)
575				}
576				for _, c := range checks {
577					if !slices.ContainsFunc(f.asked, func(q canIQuery) bool { return c.matches(q, p) }) {
578						t.Errorf("never asked: auth can-i %s %s (scope %s); asked %v", c.verb, c.resource, c.scope, f.asked)
579					}
580				}
581				// No manifest creates a Secret, so no one asks to.
582				for _, q := range f.asked {
583					if q.resource == "secrets" {
584						t.Errorf("asked about secrets (%v), no manifest creates one", q)
585					}
586				}
587				requireReadOnly(t, f)
588			})
589		}
590	}
