79	// fakePod is the Nexus pod as one round sees it.
80	type fakePod struct {
81		name  string
82		phase string
83		// scheduled is the status of the PodScheduled condition: "" (no such
84		// condition yet), "True" or "False" (then the reason is Unschedulable).
85		scheduled     string
86		unschedulable string // message of the PodScheduled=False condition
87		ready         bool
88	
89		// The state of the container; none is reported for a pod that is not scheduled.
90		waiting, waitingMessage string // reason and message of state.waiting
91		running                 bool
92		lastTerminated          string // reason of lastState.terminated
93		restarts                int
94	}
95	
96	func (pd fakePod) object() map[string]any {
97		name := pd.name
98		if name == "" {
99			name = deployPodName
100		}
101		var conds []any
102		if pd.scheduled != "" {
103			c := map[string]any{"type": "PodScheduled", "status": pd.scheduled}
104			if pd.scheduled == "False" {
105				c["reason"] = "Unschedulable"
106				c["message"] = pd.unschedulable
107			}
108			conds = append(conds, c)
109		}
110		readyStatus := "False"
111		if pd.ready {
112			readyStatus = "True"
113		}
114		conds = append(conds, map[string]any{"type": "Ready", "status": readyStatus})
115		status := map[string]any{"phase": pd.phase, "conditions": conds}
116	
117		if pd.scheduled == "True" {
118			cs := map[string]any{"name": "nexus", "ready": pd.ready, "restartCount": pd.restarts, "image": "docker.io/sonatype/nexus3"}
119			switch {
120			case pd.waiting != "":
121				cs["state"] = map[string]any{"waiting": map[string]any{"reason": pd.waiting, "message": pd.waitingMessage}}
122			case pd.running:
123				cs["state"] = map[string]any{"running": map[string]any{"startedAt": "2026-11-16T12:00:05Z"}}
124			}
125			if pd.lastTerminated != "" {
126				cs["lastState"] = map[string]any{"terminated": map[string]any{"reason": pd.lastTerminated, "exitCode": 137}}
127			}
128			status["containerStatuses"] = []any{cs}
129		}
130		return map[string]any{
131			"metadata": map[string]any{"name": name, "labels": map[string]string{"app.kubernetes.io/name": "nexus"}},
132			"status":   status,
133		}
134	}
135	
136	func creatingPod() fakePod {
137		return fakePod{phase: "Pending", scheduled: "True", waiting: "ContainerCreating"}
138	}
139	func startingPod() fakePod { return fakePod{phase: "Running", scheduled: "True", running: true} }
140	func readyPod() fakePod {
141		return fakePod{phase: "Running", scheduled: "True", running: true, ready: true}
142	}
143	func unscheduledPod() fakePod { return fakePod{phase: "Pending"} }
144	func unschedulablePod(msg string) fakePod {
145		return fakePod{phase: "Pending", scheduled: "False", unschedulable: msg}
146	}
147	func pullFailedPod(reason string) fakePod {
148		return fakePod{
149			phase: "Pending", scheduled: "True", waiting: reason,
150			waitingMessage: `Failed to pull image "docker.io/sonatype/nexus3:3.98.1": rpc error: code = Unknown`,
151		}
152	}
