410	func (c requiredCheck) matches(q canIQuery, p Params) bool {
411		if q.verb != c.verb || q.resource != c.resource {
412			return false
413		}
414		switch c.scope {
415		case "namespace":
416			return q.namespace == p.Namespace && !q.allNamespaces
417		case "all":
418			return q.allNamespaces
419		default:
420			return !q.allNamespaces
421		}
422	}
