func TestUpstreamWorkloadNamesWhatItDiagnoses(t *testing.T) {
	nexus := nexusWorkload()
	if nexus.selector != podSelector {
		t.Errorf("Nexus selector = %q, want %q", nexus.selector, podSelector)
	}
